 9→function getLastThinkingLine(segments: ContentSegment[], streamingRemainder?: string): string {
10→  // Use streaming remainder if available
11→  if (streamingRemainder?.trim()) {
12→    const lines = streamingRemainder.trim().split('\n').filter((l) => l.trim());
13→    const last = lines[lines.length - 1] || '';
14→    return last.length > 100 ? last.slice(0, 100) + '...' : last;
15→  }
16→  // Otherwise use last thinking segment's last line
17→  for (let i = segments.length - 1; i >= 0; i--) {
18→    if (segments[i].type === 'thinking' && segments[i].text?.trim()) {
19→      const lines = segments[i].text!.trim().split('\n').filter((l) => l.trim());
20→      const last = lines[lines.length - 1] || '';
21→      return last.length > 100 ? last.slice(0, 100) + '...' : last;
22→    }
23→  }
24→  return 'Thinking...';
25→}
