27→function ThinkingBlock({ segments, streamingRemainder, isActivelyStreaming }: {
28→  segments: ContentSegment[];
29→  streamingRemainder?: string;
30→  isActivelyStreaming: boolean;
31→}) {
32→  // All non-answer segments go inside the thinking block
33→  const thinkingSegments = segments.filter((s) => s.type !== 'answer');
34→  const hasContent = thinkingSegments.some(
35→    (s) => (s.type === 'thinking' && s.text?.trim()) || (s.type === 'tool' && s.toolResult)
36→  ) || streamingRemainder?.trim();
37→
38→  if (!hasContent) return null;
39→
40→  const summary = getLastThinkingLine(segments, streamingRemainder);
41→
42→  return (
43→    <details className="message-bubble__segment message-bubble__segment--thinking message-bubble__collapsible" open={isActivelyStreaming || undefined}>
44→      <summary className="message-bubble__collapsible-summary">
45→        <span className="message-bubble__segment-label">Thinking</span>
46→        <span className="message-bubble__collapsible-preview">{summary}</span>
47→      </summary>
48→      <div className="message-bubble__thinking-body">
49→        {thinkingSegments.map((seg, i) => {
50→          if (seg.type === 'thinking' && seg.text?.trim()) {
51→            return (
52→              <div key={i} className="message-bubble__segment-content">
53→                <ReactMarkdown remarkPlugins={[remarkGfm]}>{seg.text}</ReactMarkdown>
54→              </div>
55→            );
56→          }
57→          if (seg.type === 'tool' && seg.toolResult) {
58→            return (
59→              <div key={i} className="message-bubble__tool-segment">
60→                <InlineQueryResult result={seg.toolResult} />
61→              </div>
62→            );
63→          }
64→          return null;
65→        })}
66→        {streamingRemainder?.trim() && (
67→          <div className="message-bubble__segment-content">
68→            <ReactMarkdown remarkPlugins={[remarkGfm]}>{streamingRemainder}</ReactMarkdown>
69→          </div>
70→        )}
71→      </div>
72→    </details>
73→  );
74→}
