  1→import type { ToolCallResult } from '../types';
  2→
  3→interface AgentCallbacks {
  4→  onTextChunk: (text: string) => void;
  5→  onThinkingDone: () => void;
  6→  onToolCall: (pending: ToolCallResult) => void;
  7→  onToolResult: (result: ToolCallResult) => void;
  8→  onDone: (sessionId: string | null) => void;
  9→  onError: (error: string) => void;
 10→}
 11→
 12→export type { AgentCallbacks };
 13→
 14→export async function runAgentLoop(
 15→  message: string,
 16→  sessionId: string | null,
 17→  callbacks: AgentCallbacks,
 18→  signal?: AbortSignal,
 19→): Promise<void> {
 20→  try {
 21→    const response = await fetch('/api/chat', {
 22→      method: 'POST',
 23→      headers: { 'Content-Type': 'application/json' },
 24→      body: JSON.stringify({ message, session_id: sessionId }),
 25→      signal,
 26→    });
 27→
 28→    if (!response.ok) {
 29→      const errorText = await response.text();
 30→      callbacks.onError(`Server error: ${errorText}`);
 31→      return;
 32→    }
 33→
 34→    const reader = response.body?.getReader();
 35→    if (!reader) {
 36→      callbacks.onError('No response stream');
 37→      return;
 38→    }
 39→
 40→    const decoder = new TextDecoder();
 41→    let buffer = '';
 42→
 43→    while (true) {
 44→      const { done, value } = await reader.read();
 45→      if (done) break;
 46→
 47→      buffer += decoder.decode(value, { stream: true });
 48→      const lines = buffer.split('\n');
 49→      buffer = lines.pop() ?? '';
 50→
 51→      let eventType = '';
 52→      for (const line of lines) {
 53→        if (line.startsWith('event: ')) {
 54→          eventType = line.slice(7).trim();
 55→        } else if (line.startsWith('data: ')) {
 56→          const data = line.slice(6);
 57→          try {
 58→            const parsed = JSON.parse(data);
 59→            handleSSEEvent(eventType, parsed, callbacks);
 60→          } catch {
 61→            // Skip malformed JSON
 62→          }
 63→          eventType = '';
 64→        }
 65→      }
 66→    }
 67→  } catch (e: unknown) {
 68→    if (signal?.aborted) return;
 69→    const msg = e instanceof Error ? e.message : 'Connection failed';
 70→    callbacks.onError(msg);
 71→  }
 72→}
 73→
 74→export async function runAgentEditLoop(
 75→  newMessage: string,
 76→  conversationHistory: { role: string; content: string }[],
 77→  callbacks: AgentCallbacks,
 78→  signal?: AbortSignal,
 79→): Promise<void> {
 80→  try {
 81→    const response = await fetch('/api/chat/edit', {
 82→      method: 'POST',
 83→      headers: { 'Content-Type': 'application/json' },
 84→      body: JSON.stringify({
 85→        new_message: newMessage,
 86→        conversation_history: conversationHistory,
 87→      }),
 88→      signal,
 89→    });
 90→
 91→    if (!response.ok) {
 92→      const errorText = await response.text();
 93→      callbacks.onError(`Server error: ${errorText}`);
 94→      return;
 95→    }
 96→
 97→    const reader = response.body?.getReader();
 98→    if (!reader) {
 99→      callbacks.onError('No response stream');
100→      return;
101→    }
102→
103→    const decoder = new TextDecoder();
104→    let buffer = '';
105→
106→    while (true) {
107→      const { done, value } = await reader.read();
108→      if (done) break;
109→
110→      buffer += decoder.decode(value, { stream: true });
111→      const lines = buffer.split('\n');
112→      buffer = lines.pop() ?? '';
113→
114→      let eventType = '';
115→      for (const line of lines) {
116→        if (line.startsWith('event: ')) {
117→          eventType = line.slice(7).trim();
118→        } else if (line.startsWith('data: ')) {
119→          const data = line.slice(6);
120→          try {
121→            const parsed = JSON.parse(data);
122→            handleSSEEvent(eventType, parsed, callbacks);
123→          } catch {
124→            // Skip malformed JSON
125→          }
126→          eventType = '';
127→        }
128→      }
129→    }
130→  } catch (e: unknown) {
131→    if (signal?.aborted) return;
132→    const msg = e instanceof Error ? e.message : 'Connection failed';
133→    callbacks.onError(msg);
134→  }
135→}
136→
137→function handleSSEEvent(
138→  eventType: string,
139→  data: Record<string, unknown>,
140→  callbacks: AgentCallbacks,
141→) {
142→  switch (eventType) {
143→    case 'thinking':
144→    case 'answer':
145→      callbacks.onTextChunk(data.text as string);
146→      break;
147→    case 'thinking_done':
148→      callbacks.onThinkingDone();
149→      break;
150→    case 'tool_call':
151→      callbacks.onToolCall({
152→        toolCallId: (data.id as string) ?? '',
153→        toolName: (data.name as string) ?? undefined,
154→        sql: (data.sql as string) ?? '',
155→        command: (data.command as string) ?? undefined,
156→        toolInput: (data.input as Record<string, unknown>) ?? undefined,
157→        columns: [],
158→        rows: [],
159→        rowCount: 0,
160→      });
161→      break;
162→    case 'tool_result': {
163→      const result: ToolCallResult = {
164→        toolCallId: (data.id as string) ?? '',
165→        toolName: (data.name as string) ?? undefined,
166→        sql: (data.sql as string) ?? '',
167→        columns: (data.columns as string[]) ?? [],
168→        rows: (data.rows as Record<string, unknown>[]) ?? [],
169→        rowCount: (data.rowCount as number) ?? 0,
170→        error: (data.error as string) ?? undefined,
171→        output: (data.output as string) ?? undefined,
172→        rawContent: (data.content as string) ?? undefined,
173→      };
174→      callbacks.onToolResult(result);
175→      break;
176→    }
177→    case 'done':
178→      callbacks.onDone((data.session_id as string) ?? null);
179→      break;
180→    case 'error':
